<script setup lang="ts">
import { computed } from 'vue'
import data from './mznc2026.json'

// Borda scores of the MiniZinc Challenge 2026, recomputed from the official results.json
// (incl. reference entries). Generated by O4A-Hands-On-CP-SAT/scripts/mznc2026_summary.py
const props = withDefaults(defineProps<{ category?: 'free' | 'parallel', top?: number }>(), {
  category: 'free',
  top: 12,
})

const rows = computed(() => (props.category === 'free' ? data.ranking_free : data.ranking_parallel).slice(0, props.top))
const max = computed(() => Math.max(...rows.value.map(r => r.score)))
</script>

<template>
  <div class="viz-root">
    <div class="legend">
      <span><i class="swatch cpsat" />CP-SAT</span>
      <span><i class="swatch mip" />MIP solvers</span>
      <span><i class="swatch other" />other CP / SAT solvers</span>
      <span class="muted">* reference entry, not eligible for prizes</span>
    </div>
    <div
      v-for="(row, i) in rows"
      :key="row.solver"
      class="row"
      :title="`#${i + 1} ${row.solver}: ${row.score.toLocaleString('en-US')} points`"
    >
      <div class="rank">{{ i + 1 }}</div>
      <div class="label" :class="{ strong: row.group !== 'other' }">
        {{ row.solver }}<span v-if="row.reference" class="muted">*</span>
      </div>
      <div class="track">
        <div class="bar" :class="row.group" :style="{ width: `${(row.score / max) * 82}%` }" />
        <span class="value">{{ Math.round(row.score).toLocaleString('en-US') }}</span>
      </div>
    </div>
  </div>
</template>

